if package == 'codex':
    package_json['files'] = ['bin/codex.js']
    package_json['optionalDependencies'] = {CODEX_PLATFORM_PACKAGES[platform_package]['npm_name']: f'npm:{CODEX_NPM_NAME}@{compute_platform_package_version(version, CODEX_PLATFORM_PACKAGES[platform_package]['npm_tag'])}' for platform_package in PACKAGE_EXPANSIONS['codex'] if platform_package != 'codex'}
elif package == 'codex-sdk':
    scripts = package_json.get('scripts')
    if isinstance(scripts, dict):
        scripts.pop('prepare', None)
    dependencies = package_json.get('dependencies')
    if not isinstance(dependencies, dict):
        dependencies = {}
    dependencies[CODEX_NPM_NAME] = version
    package_json['dependencies'] = dependencies

if target is None:
    supported = ', '.join(sorted(TARGET_SPECS))
    raise RuntimeError(f'Unsupported host platform {platform.system()}/{platform.machine()}. Pass --target explicitly. Supported targets: {supported}')

if package_dir.exists():
    if not package_dir.is_dir():
        raise RuntimeError(f'Package output exists and is not a directory: {package_dir}')
    if any(package_dir.iterdir()):
        if not force:
            raise RuntimeError(f'Package output directory is not empty: {package_dir}. Pass --force to replace it.')
        shutil.rmtree(package_dir)

for relative_dir in required_dirs:
    path = package_dir / relative_dir
    if not path.is_dir():
        raise RuntimeError(f'Missing package directory: {relative_dir}')

for key, expected in expected_metadata.items():
    actual = metadata.get(key)
    if actual != expected:
        raise RuntimeError(f'Invalid package metadata field {key!r}: expected {expected!r}, got {actual!r}')

for relative_file in required_files:
    path = package_dir / relative_file
    if not path.is_file():
        raise RuntimeError(f'Missing package file: {relative_file}')

if not spec.is_windows:
    for relative_file in executable_files:
        path = package_dir / relative_file
        if not is_executable(path):
            raise RuntimeError(f'Package file is not executable: {relative_file}')

if codex_version is not None:
    runtime_version = normalize_codex_version(codex_version)
    pyproject_text, count = re.subn(f'"{re.escape(RUNTIME_DISTRIBUTION_NAME)}==[^"]+"', f'"{RUNTIME_DISTRIBUTION_NAME}=={runtime_version}"', pyproject_text)
    if count != 1:
        raise RuntimeError(f'Expected exactly one {RUNTIME_DISTRIBUTION_NAME} dependency pin in sdk/python/pyproject.toml')

try:
    requirements['require_runtime_version'](runtime_versions[0])
except ValueError as exc:
    raise RuntimeError(f'Cannot package the Python SDK: {exc}') from exc

if package_source.is_dir():
    source = package_source.resolve()
    destination = staging_dir.resolve()
    if source.is_relative_to(destination) or destination.is_relative_to(source):
        raise RuntimeError('Codex package and runtime staging directories must not overlap')
    for path in package_source.rglob('*'):
        if path.is_symlink() or not (path.is_file() or path.is_dir()):
            raise RuntimeError(f'Expected a regular Codex package entry: {path}')

if package_source.is_dir():
    shutil.copytree(package_source, runtime_package_root, dirs_exist_ok=True)
    _validate_codex_package_layout(runtime_package_root, package_source)
else:
    _extract_codex_package_archive(package_source, runtime_package_root)

for entry in ('bin', 'codex-resources', 'codex-path'):
    if not (package_dir / entry).is_dir():
        missing_entries.append(entry)

if missing_entries:
    missing = ', '.join(missing_entries)
    raise RuntimeError(f'Missing Codex package layout entries in {package_source}: {missing}')

